///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.digitalChangePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param tab
 * @returns
 * @hidden N
*/
scwin.digitalChangePage = async function (tab) {
    /* sdd-asis-lifecycle:begin fn_DigitalChangePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.digitalListForm || { elements: [] });
    const lastSaveStatCdInt = parseInt($c.util.getComponent('dma_DigitalChangePageReq').get('lastSaveStatCd'));
    if (lastSaveStatCdInt == 0 && tab > 1) {
        await $c.win.alert('발행증권에 관한 사항을 먼저 저장해주세요.');
        return;
    } else {
        if (lastSaveStatCdInt == 1 && tab > 2) {
            await $c.win.alert('상장신청인에 관한 사항을 먼저 저장해주세요.');
            return;
        } else {
            if (lastSaveStatCdInt == 2 && tab > 3) {
                await $c.win.alert('기타사항을 먼저 저장해주세요.');
                return;
            }
        }
    }
    if (tab == 1) {
        $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewIsuTab');
    } else {
        if (tab == 2) {
            return;
        } else {
            if (tab == 3) {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewSrtyLpTab');
            } else {
                $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'viewAttachFileTab');
            }
        }
    }
    scwin.form.action = 'DigitalList.do';
    await scwin.tx_fn_DigitalChangePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.lc.fn_isProcess('I')) {
        return;
    }
    if ($c.util.getComponent('ipt_applStatusCd').getValue() === '02') {
        await $c.win.alert('반송된 신청입니다. 발행증권에 관한 사항 탭부터 다시 저장해야 합니다.');
        return;
    }
    scwin.removeComma(2);
    if (!fn_validate(2)) {
        scwin.insertComma(2);
        return;
    }
    if (!await scwin.valid()) {
        scwin.insertComma(2);
        return;
    }
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = 'DigitalList.do';
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'saveIsurTab');
    await scwin.tx_fn_Register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.valid
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.valid = async function () {
    /* sdd-asis-lifecycle:begin fn_valid — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($("input[name='audtrNm']").val() === '' || $("input[name='audtrNm']").val() == null) {
        await $c.win.alert("최근 사업년도 외부감사 기관은 필수입니다.");
        return false;
    }
    if (($c.util.getComponent('slc_audtOpinTpCd').getValue() == null ? '' : String($c.util.getComponent('slc_audtOpinTpCd').getValue())) === '' || $c.util.getComponent('slc_audtOpinTpCd').getValue() == null || $c.util.getComponent('slc_audtOpinTpCd').getValue() === '6') {
        await $c.win.alert("최근 사업년도 외부감사 결과는 필수입니다.");
        return false;
    }
    if ($("input[name='totAsstAmt']").val() === '' || $("input[name='totAsstAmt']").val() == null) {
        await $c.win.alert("최근 사업년도 자산총계(원)는 필수입니다.");
        return false;
    }
    if ($("input[name='totDebtAmt']").val() === '' || $("input[name='totDebtAmt']").val() == null) {
        await $c.win.alert("최근 사업년도 부채총계(원)는 필수입니다.");
        return false;
    }
    if ($("input[name='totCap']").val() === '' || $("input[name='totCap']").val() == null) {
        await $c.win.alert("최근 사업년도 자기자본총계(원)는 필수입니다.");
        return false;
    }
    if ($("input[name='cap']").val() === '' || $("input[name='cap']").val() == null) {
        await $c.win.alert("최근 사업년도 자본금(원)는 필수입니다.");
        return false;
    }
    if ($("input[name='sales']").val() === '' || $("input[name='sales']").val() == null) {
        await $c.win.alert("최근 사업년도 매출액(원)는 필수입니다.");
        return false;
    }
    if ($("input[name='contbzProftAmt']").val() === '' || $("input[name='contbzProftAmt']").val() == null) {
