/**
 * @method
 * @name scwin.digitalSub
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.digitalSub = async function () {
    /* sdd-asis-lifecycle:begin fn_DigitalSub — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.lc.fn_isProcess('S')) {
        return;
    }
    scwin.form = (document.digitalListForm || { elements: [] });
    scwin.form.action = "DigitalList.do";
    $c.util.getComponent('dma_DigitalChangePageReq').set('method', 'submitList');
    await scwin.tx_fn_DigitalSub();
    /* sdd-asis-lifecycle:end */
};


